<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class superbed extends cloudStorage2 { var $host = array('superbed.cn', 'pic.imgdb.cn'); public function init() { $this->token = $this->options->cloud_storage_superbed_token; $this->silent_scanning = $this->options->cloud_storage_superbed_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_superbed_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $url = 'https://api.superbed.cn/upload'; $post_data = array( 'token' => $this->token, 'file' => function_exists('curl_file_create') ? curl_file_create($source_path) : "@{$source_path}", 'queue' => 'max', 'categories' => apply_filters( 'qqworld-collector-cloud-storage-superbed-categories', '' ), 'v' => 2 ); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/66.0.3359.181 Safari/537.36"); curl_setopt($ch, CURLOPT_POST, 1); curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false); $result = curl_exec($ch); curl_close($ch); if ($result) { $result = json_decode($result, true); if (!$result['err']) return $result['url']; else do_action( 'qqworld-collector-log', $this->log_id, 'superbed failed: ', print_r($result, true) ); } else { do_action( 'qqworld-collector-log', $this->log_id, 'superbed failed: ', 'nothings return.' ); } return false; } public function add_could_storage_form($guid) { $this->accessed = $this->is_current; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>